{"code": "import subprocess, glob, os

# Check cron output directory
log_dir = os.path.expanduser("~/.hermes/cron/output/")
print(f"Directory exists: {os.path.exists(log_dir)}")
if os.path.exists(log_dir):
    all_files = os.listdir(log_dir)
    print(f"All files: {all_files[:20]}")

# Also check for any cron logs elsewhere
for pattern in ["~/.hermes/cron/*log*", "~/.hermes/logs/cron*", "/var/log/cron*", "~/.hermes/*.log"]:
    matches = glob.glob(os.path.expanduser(pattern))
    if matches:
        print(f"\nFound logs for pattern {pattern}:")
        for m in matches:
            print(f"  {m}")

# Check Hermes process status
result = subprocess.run(["ps", "aux"], capture_output=True, text=True)
for line in result.stdout.split("\n"):
    if "hermes" in line.lower() and "grep" not in line.lower():
        print(f"Process: {line}")
"}

